FILES['src/pegasus/registries/population.py'] = '\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Literal\n\n\nPopulationTensorMode = Literal[\n    "independent_denominator",\n    "sim_informed_denominator",\n]\n\n\nclass PopulationRegistryError(ValueError):\n    """Raised when a population tensor solver request violates registry constraints."""\n\n\nclass PopulationTensorScaleError(PopulationRegistryError):\n    """Raised when a dense population tensor request exceeds the allowed scale."""\n\n\n@dataclass(frozen=True)\nclass PopulationSolverSpec:\n    solver_id: str\n    mode: str\n    backend: str\n    sparse_jacobian: bool\n    max_cells: int\n    status: str\n    warning_code: str | None = None\n\n    def as_manifest(self) -> dict[str, object]:\n        return {\n            "solver_id": self.solver_id,\n            "mode": self.mode,\n            "backend": self.backend,\n            "sparse_jacobian": self.sparse_jacobian,\n            "max_cells": self.max_cells,\n            "status": self.status,\n            "warning_code": self.warning_code,\n        }\n\n\nSOLVER_REGISTRY_VERSION = "population_solver_registry_v1"\nDENSE_NATIONAL_CELL_THRESHOLD = 50_000\n\nPOPULATION_SOLVERS: dict[str, PopulationSolverSpec] = {\n    "independent_sidra_anchor_v1": PopulationSolverSpec(\n        solver_id="independent_sidra_anchor_v1",\n        mode="independent_denominator",\n        backend="algebraic_sidra_anchor_identity",\n        sparse_jacobian=True,\n        max_cells=DENSE_NATIONAL_CELL_THRESHOLD,\n        status="active",\n    ),\n    "sim_informed_sparse_admm_scaffold_v1": PopulationSolverSpec(\n        solver_id="sim_informed_sparse_admm_scaffold_v1",\n        mode="sim_informed_denominator",\n        backend="sparse_admm_scaffold_blocked_feedback",\n        sparse_jacobian=True,\n        max_cells=DENSE_NATIONAL_CELL_THRESHOLD,\n        status="warning_scaffold",\n        warning_code="sim_informed_population_feedback_risk",\n    ),\n}\n\n\ndef registry_manifest() -> dict[str, object]:\n    return {\n        "schema_version": "1.0",\n        "registry_version": SOLVER_REGISTRY_VERSION,\n        "dense_national_cell_threshold": DENSE_NATIONAL_CELL_THRESHOLD,\n        "solvers": {key: value.as_manifest() for key, value in POPULATION_SOLVERS.items()},\n    }\n\n\ndef get_population_solver(solver_id: str) -> PopulationSolverSpec:\n    try:\n        return POPULATION_SOLVERS[solver_id]\n    except KeyError as exc:\n        raise PopulationRegistryError(f"Unknown population tensor solver: {solver_id}") from exc\n\n\ndef select_population_solver(*, mode: str, solver_id: str | None = None) -> PopulationSolverSpec:\n    if solver_id is not None:\n        spec = get_population_solver(solver_id)\n        if spec.mode != mode:\n            raise PopulationRegistryError(f"Solver {solver_id} has mode {spec.mode}, not requested mode {mode}.")\n        return spec\n\n    for spec in POPULATION_SOLVERS.values():\n        if spec.mode == mode:\n            return spec\n    raise PopulationRegistryError(f"No population tensor solver registered for mode: {mode}")\n\n\ndef estimate_population_tensor_cells(*, localities: int, periods: int, strata: int = 1) -> int:\n    if localities < 0 or periods < 0 or strata < 0:\n        raise PopulationRegistryError("Population tensor dimensions must be nonnegative.")\n    return int(localities) * int(periods) * int(strata)\n\n\ndef assert_dense_population_tensor_allowed(\n    *,\n    localities: int,\n    periods: int,\n    strata: int = 1,\n    threshold: int = DENSE_NATIONAL_CELL_THRESHOLD,\n) -> int:\n    cells = estimate_population_tensor_cells(localities=localities, periods=periods, strata=strata)\n    if cells > threshold:\n        raise PopulationTensorScaleError(\n            "dense national population tensor request exceeds scale threshold: "\n            f"cells={cells} threshold={threshold}. Use sparse/block solver planning instead."\n        )\n    return cells\n'
FILES['src/pegasus/she/population/schema.py'] = '\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Any, Literal\n\nfrom pegasus.core.schemas import DenominatorContract\n\n\nPopulationTensorMode = Literal["independent_denominator", "sim_informed_denominator"]\n\n\ndef official_sidra_anchor_contract(\n    *,\n    source: str = "SIDRA",\n    warnings: list[str] | None = None,\n) -> DenominatorContract:\n    return DenominatorContract(\n        mode="official_sidra_anchor",\n        source=source,\n        denominator_field_id="sidra_population_total",\n        support_json={"role": "official_population_anchor"},\n        uncertainty_json={"source_uncertainty": "official_statistical_series"},\n        warnings=warnings or [],\n    )\n\n\ndef blocked_missing_population_contract(\n    *,\n    reason: str,\n) -> DenominatorContract:\n    return DenominatorContract(\n        mode="blocked_missing",\n        source="none",\n        denominator_field_id=None,\n        support_json={},\n        uncertainty_json={"blocked_reason": reason},\n        warnings=[reason],\n    )\n\n\n@dataclass(frozen=True)\nclass PopulationTensorRequest:\n    mode: PopulationTensorMode\n    solver_id: str\n    solver_backend: str\n    locality_ids: tuple[str, ...]\n    periods: tuple[str, ...]\n    strata: tuple[str, ...] = ("total",)\n    require_sparse: bool = True\n\n    @property\n    def n_cells(self) -> int:\n        return len(self.locality_ids) * len(self.periods) * len(self.strata)\n\n    def support(self) -> dict[str, Any]:\n        return {\n            "locality_ids": list(self.locality_ids),\n            "periods": list(self.periods),\n            "strata": list(self.strata),\n            "n_cells": self.n_cells,\n        }\n\n\n@dataclass(frozen=True)\nclass PopulationTensorDiagnostics:\n    n_cells: int\n    solver_backend: str\n    sparse_jacobian: bool\n    reconstruction_uncertainty: float\n    denominator_feedback_warning: bool\n    dense_abort_threshold: int\n    warnings: tuple[str, ...] = field(default_factory=tuple)\n\n    def as_manifest(self) -> dict[str, Any]:\n        return {\n            "n_cells": self.n_cells,\n            "solver_backend": self.solver_backend,\n            "sparse_jacobian": self.sparse_jacobian,\n            "reconstruction_uncertainty": self.reconstruction_uncertainty,\n            "denominator_feedback_warning": self.denominator_feedback_warning,\n            "dense_abort_threshold": self.dense_abort_threshold,\n            "warnings": list(self.warnings),\n        }\n\n\n@dataclass(frozen=True)\nclass PopulationTensorResult:\n    tensor_id: str\n    mode: PopulationTensorMode\n    solver_id: str\n    solver_backend: str\n    sparse_jacobian: bool\n    value: float\n    unit: str\n    locality_id: str\n    period: str\n    source_anchor_field_id: str\n    source_table_id: str\n    source_variable_id: str\n    source_request_hash: str\n    source_metadata_hash: str\n    reconstruction_uncertainty: float\n    denominator_feedback_warning: bool\n    state: str\n    warnings: tuple[str, ...]\n    diagnostics: PopulationTensorDiagnostics\n\n    def as_manifest(self) -> dict[str, Any]:\n        return {\n            "tensor_id": self.tensor_id,\n            "PopulationTensorMode": self.mode,\n            "SolverBackend": self.solver_backend,\n            "SolverID": self.solver_id,\n            "SparseJacobian": self.sparse_jacobian,\n            "value": self.value,\n            "unit": self.unit,\n            "locality_id": self.locality_id,\n            "period": self.period,\n            "source_anchor_field_id": self.source_anchor_field_id,\n            "source_table_id": self.source_table_id,\n            "source_variable_id": self.source_variable_id,\n            "source_request_hash": self.source_request_hash,\n            "source_metadata_hash": self.source_metadata_hash,\n            "reconstruction_uncertainty": self.reconstruction_uncertainty,\n            "DenominatorFeedbackWarning": self.denominator_feedback_warning,\n            "state": self.state,\n            "warnings": list(self.warnings),\n            "diagnostics": self.diagnostics.as_manifest(),\n        }\n'
FILES['src/pegasus/she/population/diagnostics.py'] = '\nfrom __future__ import annotations\n\nfrom pegasus.registries.population import DENSE_NATIONAL_CELL_THRESHOLD, PopulationSolverSpec\nfrom pegasus.she.population.schema import PopulationTensorDiagnostics, PopulationTensorRequest\n\n\ndef population_tensor_diagnostics(\n    *,\n    request: PopulationTensorRequest,\n    solver: PopulationSolverSpec,\n    reconstruction_uncertainty: float,\n    denominator_feedback_warning: bool,\n    warnings: list[str] | tuple[str, ...] | None = None,\n) -> PopulationTensorDiagnostics:\n    return PopulationTensorDiagnostics(\n        n_cells=request.n_cells,\n        solver_backend=solver.backend,\n        sparse_jacobian=solver.sparse_jacobian,\n        reconstruction_uncertainty=float(reconstruction_uncertainty),\n        denominator_feedback_warning=bool(denominator_feedback_warning),\n        dense_abort_threshold=DENSE_NATIONAL_CELL_THRESHOLD,\n        warnings=tuple(warnings or ()),\n    )\n'
FILES['src/pegasus/she/population/sparse_admm.py'] = '\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Any\n\n\n@dataclass(frozen=True)\nclass SparseADMMScaffold:\n    solver_id: str\n    status: str\n    reason: str\n    sparse_jacobian: bool\n    warnings: tuple[str, ...]\n\n    def as_manifest(self) -> dict[str, Any]:\n        return {\n            "solver_id": self.solver_id,\n            "status": self.status,\n            "reason": self.reason,\n            "sparse_jacobian": self.sparse_jacobian,\n            "warnings": list(self.warnings),\n        }\n\n\ndef build_sim_informed_sparse_admm_scaffold(*, solver_id: str) -> SparseADMMScaffold:\n    return SparseADMMScaffold(\n        solver_id=solver_id,\n        status="blocked_feedback_scaffold",\n        reason=(\n            "SIM-informed population tensor mode is architecturally visible but remains warning-only "\n            "until calibrated feedback loss and uncertainty propagation are implemented."\n        ),\n        sparse_jacobian=True,\n        warnings=("sim_informed_population_feedback_risk",),\n    )\n'
FILES['src/pegasus/she/population/solvers.py'] = '\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nfrom pegasus.core.hashing import content_hash\nfrom pegasus.registries.population import (\n    DENSE_NATIONAL_CELL_THRESHOLD,\n    assert_dense_population_tensor_allowed,\n    select_population_solver,\n)\nfrom pegasus.she.population.diagnostics import population_tensor_diagnostics\nfrom pegasus.she.population.schema import PopulationTensorRequest, PopulationTensorResult\nfrom pegasus.she.population.sidra_anchor import load_sidra_population_total_anchor\nfrom pegasus.she.population.sparse_admm import build_sim_informed_sparse_admm_scaffold\n\n\ndef solve_population_tensor_from_sidra_anchor(\n    *,\n    sidra_facts_path: str | Path,\n    mode: str = "independent_denominator",\n    solver_id: str | None = None,\n    dense_localities: int | None = None,\n    dense_periods: int | None = None,\n    dense_strata: int = 1,\n) -> PopulationTensorResult:\n    sidra_facts_path = Path(sidra_facts_path)\n    anchor = load_sidra_population_total_anchor(sidra_facts_path)\n    solver = select_population_solver(mode=mode, solver_id=solver_id)\n\n    locality_count = dense_localities if dense_localities is not None else 1\n    period_count = dense_periods if dense_periods is not None else 1\n    assert_dense_population_tensor_allowed(\n        localities=locality_count,\n        periods=period_count,\n        strata=dense_strata,\n        threshold=solver.max_cells,\n    )\n\n    request = PopulationTensorRequest(\n        mode=mode,  # type: ignore[arg-type]\n        solver_id=solver.solver_id,\n        solver_backend=solver.backend,\n        locality_ids=(anchor.locality_id,),\n        periods=(anchor.period,),\n        strata=("total",),\n        require_sparse=True,\n    )\n\n    warnings: list[str] = []\n    reconstruction_uncertainty = 0.0\n    denominator_feedback_warning = False\n    state = "verified"\n\n    if mode == "sim_informed_denominator":\n        scaffold = build_sim_informed_sparse_admm_scaffold(solver_id=solver.solver_id)\n        warnings.extend(scaffold.warnings)\n        reconstruction_uncertainty = 0.05\n        denominator_feedback_warning = True\n        state = "fragile"\n    elif mode != "independent_denominator":\n        raise ValueError(f"Unsupported population tensor mode: {mode}")\n\n    diagnostics = population_tensor_diagnostics(\n        request=request,\n        solver=solver,\n        reconstruction_uncertainty=reconstruction_uncertainty,\n        denominator_feedback_warning=denominator_feedback_warning,\n        warnings=warnings,\n    )\n\n    payload = {\n        "mode": mode,\n        "solver_id": solver.solver_id,\n        "sidra_facts_path": str(sidra_facts_path),\n        "anchor_field_id": anchor.field_id,\n        "locality_id": anchor.locality_id,\n        "period": anchor.period,\n        "value": anchor.value,\n        "metadata_hash": anchor.metadata_hash,\n    }\n\n    return PopulationTensorResult(\n        tensor_id=content_hash(payload),\n        mode=mode,  # type: ignore[arg-type]\n        solver_id=solver.solver_id,\n        solver_backend=solver.backend,\n        sparse_jacobian=solver.sparse_jacobian,\n        value=anchor.value,\n        unit=anchor.unit,\n        locality_id=anchor.locality_id,\n        period=anchor.period,\n        source_anchor_field_id=anchor.field_id,\n        source_table_id=anchor.table_id,\n        source_variable_id=anchor.variable_id,\n        source_request_hash=anchor.request_hash,\n        source_metadata_hash=anchor.metadata_hash,\n        reconstruction_uncertainty=reconstruction_uncertainty,\n        denominator_feedback_warning=denominator_feedback_warning,\n        state=state,\n        warnings=tuple(warnings),\n        diagnostics=diagnostics,\n    )\n\n\ndef dense_national_abort_check(*, localities: int, periods: int, strata: int = 1) -> int:\n    return assert_dense_population_tensor_allowed(\n        localities=localities,\n        periods=periods,\n        strata=strata,\n        threshold=DENSE_NATIONAL_CELL_THRESHOLD,\n    )\n'
FILES['src/pegasus/output/population_tensor_bundle.py'] = '\nfrom __future__ import annotations\n\nimport json\nimport platform\nimport sys\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\nimport pyarrow as pa\nimport pyarrow.parquet as pq\nimport polars as pl\n\nfrom pegasus.core.hashing import sha256_file\nfrom pegasus.output.bundle import create_empty_output_bundle\nfrom pegasus.output.reproducibility import COMPILE_TELEMETRY_STAGES\nfrom pegasus.output.validate import validate_output_bundle\nfrom pegasus.registries.population import registry_manifest\nfrom pegasus.she.population.schema import PopulationTensorResult\nfrom pegasus.she.population.solvers import solve_population_tensor_from_sidra_anchor\n\n\ndef _now() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef _json(value: Any) -> str:\n    return json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, default=str)\n\n\ndef _compact(value: Any) -> str:\n    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)\n\n\ndef _write_rows_like(path: Path, rows: list[dict[str, Any]]) -> None:\n    schema = pq.read_table(path).schema\n    shaped = [{name: row.get(name) for name in schema.names} for row in rows]\n    table = pa.Table.from_pylist(shaped, schema=schema) if shaped else pa.Table.from_arrays([pa.array([], type=f.type) for f in schema], schema=schema)\n    pq.write_table(table, path)\n\n\ndef _field(result: PopulationTensorResult) -> dict[str, Any]:\n    support = {\n        "PopulationTensorMode": result.mode,\n        "SolverBackend": result.solver_backend,\n        "SolverID": result.solver_id,\n        "SparseJacobian": result.sparse_jacobian,\n        "DenominatorFeedbackWarning": result.denominator_feedback_warning,\n        "reconstruction_uncertainty": result.reconstruction_uncertainty,\n        "locality_id": result.locality_id,\n        "period": result.period,\n        "n_events": result.value,\n        "n_eff": result.value,\n        "missingness": 0.0,\n        "denom_fragility": result.reconstruction_uncertainty,\n        "population_tensor_diagnostics": result.diagnostics.as_manifest(),\n    }\n    axes = {\n        "geography_axis": "IBGE_COD7",\n        "time_axis": "year",\n        "population_strata_axis": "total",\n        "population_tensor_mode": result.mode,\n    }\n    return {\n        "field_id": f"population_tensor_{result.mode}",\n        "name": "PopulationTensorOfficialSIDRAIndependent" if result.mode == "independent_denominator" else "PopulationTensorSIMInformedWarningScaffold",\n        "kind": "latent_context" if result.mode == "sim_informed_denominator" else "extensive_measure",\n        "carrier": "Population",\n        "unit": result.unit,\n        "support_json": _compact(support),\n        "axes_json": _compact(axes),\n        "aggregation": "additive",\n        "role_json": _compact(["population_denominator_tensor", result.mode]),\n        "source_json": _compact(["SIDRA", "population_tensor"]),\n        "operator": "PopulationTensor/IndependentSIDRAAnchor" if result.mode == "independent_denominator" else "PopulationTensor/SIMInformedWarningScaffold",\n        "provenance_json": _compact(["official_sidra_anchor", "population_tensor", result.solver_id]),\n        "state": result.state,\n        "warnings_json": _compact(list(result.warnings)),\n        "lineage_json": _compact({"parent_ids": [result.source_anchor_field_id], "operator": "population_tensor_solver", "created_at": _now(), "tensor_id": result.tensor_id}),\n        "materialization_state": "materialized",\n        "path": "Tables/population_tensor_diagnostics.parquet",\n        "dashboard_safe": "warning" if result.warnings else "true",\n    }\n\n\ndef _q_row(field: dict[str, Any], result: PopulationTensorResult) -> dict[str, Any]:\n    return {\n        "field_id": field["field_id"],\n        "n_events": result.value,\n        "n_denom": result.value,\n        "n_eff": result.value,\n        "cov_S": 1.0,\n        "cov_T": 1.0,\n        "missingness": 0.0,\n        "zero_inflation": 0.0,\n        "denom_fragility": result.reconstruction_uncertainty,\n        "cv": result.reconstruction_uncertainty,\n        "moran_i": None,\n        "temporal_roughness": None,\n        "spatial_entropy": None,\n        "provenance_risk": 0.05 if result.mode == "independent_denominator" else 0.35,\n        "race_axis_source": None,\n        "race_axis_target": None,\n        "missing_race_share": None,\n        "emission_prior_strength": None,\n        "race_bridge_cv": None,\n        "sensitivity_width": None,\n        "bridge_mode": None,\n        "state": result.state,\n        "dashboard_safe": field["dashboard_safe"],\n        "warnings_json": _compact(list(result.warnings)),\n        "computed_at": _now(),\n        "q_schema_version": "1.0",\n    }\n\n\ndef _vd_row(field: dict[str, Any], result: PopulationTensorResult) -> dict[str, Any]:\n    return {\n        "field_id": field["field_id"],\n        "name": field["name"],\n        "definition": "Population denominator tensor reconstructed from the official SIDRA 9606 total population anchor.",\n        "estimand": result.mode,\n        "interpretation_warning": "Independent denominator mode does not use SIM feedback." if result.mode == "independent_denominator" else "SIM-informed mode is warning-only until calibrated feedback uncertainty is implemented.",\n        "unit": field["unit"],\n        "source_system": "SIDRA",\n        "carrier": field["carrier"],\n        "role_json": field["role_json"],\n        "state": field["state"],\n        "dashboard_safe": field["dashboard_safe"],\n    }\n\n\ndef _warning_rows(field: dict[str, Any], result: PopulationTensorResult) -> list[dict[str, Any]]:\n    rows = [\n        {\n            "warning_id": "population_tensor_official_sidra_anchor_used",\n            "field_id": field["field_id"],\n            "source": "population_tensor",\n            "severity": "info",\n            "code": "independent_population_denominator_mode",\n            "message": "Population tensor uses official SIDRA denominator independently from SIM events.",\n            "inherited_from_json": "[]",\n            "created_at": _now(),\n        }\n    ]\n    if result.denominator_feedback_warning:\n        rows.append(\n            {\n                "warning_id": "population_tensor_sim_feedback_risk",\n                "field_id": field["field_id"],\n                "source": "population_tensor",\n                "severity": "warning",\n                "code": "sim_informed_population_feedback_risk",\n                "message": "SIM-informed denominator mode can feed numerator measurement noise back into denominator reconstruction; this slice emits warning metadata only.",\n                "inherited_from_json": "[]",\n                "created_at": _now(),\n            }\n        )\n    return rows\n\n\ndef _failed_dense_branch(field: dict[str, Any]) -> dict[str, Any]:\n    return {\n        "failed_branch_id": "failed_dense_national_population_tensor_above_threshold",\n        "attempted_operator": "dense_national_projected_gradient_population_tensor",\n        "parent_field_ids": _compact([field["field_id"]]),\n        "failure_stage": "SHE.population_tensor",\n        "failed_terms": _compact(["dense_national_solver", "population_tensor_scale_gate"]),\n        "reason": "Dense national population tensor projected-gradient path must abort above the configured scale threshold; sparse/block solver planning is required.",\n        "warnings_json": _compact(["dense_national_population_tensor_aborted_above_threshold"]),\n        "created_at": _now(),\n    }\n\n\ndef write_population_tensor_fixture_bundle(\n    *,\n    sidra_facts_path: str | Path,\n    run_dir: str | Path,\n    mode: str = "independent_denominator",\n) -> Path:\n    sidra_facts_path = Path(sidra_facts_path)\n    run_dir = Path(run_dir)\n    create_empty_output_bundle(run_dir)\n    result = solve_population_tensor_from_sidra_anchor(sidra_facts_path=sidra_facts_path, mode=mode)\n    field = _field(result)\n    q_rows = [_q_row(field, result)]\n    vd_rows = [_vd_row(field, result)]\n    warning_rows = _warning_rows(field, result)\n    failed_rows = [_failed_dense_branch(field)]\n\n    _write_rows_like(run_dir / "V_fields.parquet", [field])\n    _write_rows_like(run_dir / "Q_tensor.parquet", q_rows)\n    _write_rows_like(run_dir / "VariableDictionary.parquet", vd_rows)\n    _write_rows_like(run_dir / "Warnings.parquet", warning_rows)\n    _write_rows_like(run_dir / "FailedBranches.parquet", failed_rows)\n    _write_rows_like(run_dir / "E_DAG.parquet", [])\n    for name in [\n        "ModelAssociations.parquet",\n        "ResidualAssociations.parquet",\n        "Hypotheses.parquet",\n        "QuarantinedFields.parquet",\n        "ForcedFields.parquet",\n    ]:\n        _write_rows_like(run_dir / name, [])\n\n    (run_dir / "Tables").mkdir(exist_ok=True)\n    pl.DataFrame([result.as_manifest()]).write_parquet(run_dir / "Tables" / "population_tensor_diagnostics.parquet")\n\n    stage_status = {stage: "skipped" for stage in COMPILE_TELEMETRY_STAGES}\n    stage_wall_seconds = {stage: 0.0 for stage in COMPILE_TELEMETRY_STAGES}\n    for stage in ["sidra_fetch", "she_build", "population_solver", "efg_build", "q_tensor", "output_serialization", "output_validation"]:\n        if stage in stage_status:\n            stage_status[stage] = "success"\n    for stage in ["stdfm", "pirs_model", "pirs_hsic"]:\n        if stage in stage_status:\n            stage_status[stage] = "blocked"\n    telemetry = {\n        "total_wall_seconds": 0.0,\n        "stage_status": stage_status,\n        "stage_wall_seconds": stage_wall_seconds,\n        "stage_errors": {\n            "stdfm": "ST-DFM is outside Slice 6A population tensor foundation.",\n            "pirs_model": "PIRS modeling is outside Slice 6A population tensor foundation.",\n            "pirs_hsic": "HSIC scanning is outside Slice 6A population tensor foundation.",\n        },\n        "resource_summary": {\n            "peak_rss_mb": None,\n            "peak_vram_mb": None,\n            "duckdb_temp_bytes": None,\n            "rows_read": {"sidra_facts": 1},\n            "rows_written": {"V_fields": 1, "Q_tensor": 1, "VariableDictionary": 1, "FailedBranches": 1},\n            "parquet_bytes_written": 0,\n        },\n    }\n\n    population_manifest = result.as_manifest()\n    user_intent = {\n        "workflow": "slice6a_population_tensor_fixture",\n        "population_tensor_mode": mode,\n        "source_systems": ["SIDRA"],\n    }\n    run_config = {\n        "schema_version": "1.0",\n        "workflow": "slice6a_population_tensor_fixture",\n        "source_systems": ["SIDRA"],\n        "source_hashes": {"sidra_facts": sha256_file(sidra_facts_path)},\n        "registry_hashes": {"population": registry_manifest()["registry_version"]},\n        "population_tensor": population_manifest,\n    }\n    manifest = {\n        "schema_version": "1.0",\n        "run_id": run_dir.name,\n        "generated_at": _now(),\n        "workflow": "slice6a_population_tensor_fixture",\n        "source_hashes": run_config["source_hashes"],\n        "registry_hashes": run_config["registry_hashes"],\n        "telemetry": telemetry,\n        "population_tensor": population_manifest,\n        "environment": {"python": sys.version.split()[0], "platform": platform.platform()},\n    }\n    p_vector = {\n        "source_systems": ["SIDRA"],\n        "field_count": 1,\n        "blocked_outputs": [row["failed_branch_id"] for row in failed_rows],\n        "population_tensor": population_manifest,\n        "provenance": {field["field_id"]: json.loads(field["provenance_json"])},\n    }\n    (run_dir / "UserIntent.json").write_text(_json(user_intent), encoding="utf-8")\n    (run_dir / "RunConfig.json").write_text(_json(run_config), encoding="utf-8")\n    (run_dir / "ReproducibilityManifest.json").write_text(_json(manifest), encoding="utf-8")\n    (run_dir / "P_vector.json").write_text(_json(p_vector), encoding="utf-8")\n    validate_output_bundle(run_dir=str(run_dir))\n    return run_dir\n'
FILES['src/pegasus/workflows/population.py'] = '\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nfrom pegasus.output.population_tensor_bundle import write_population_tensor_fixture_bundle\nfrom pegasus.output.validate import validate_output_bundle\nfrom pegasus.she.population.solvers import dense_national_abort_check, solve_population_tensor_from_sidra_anchor\n\n\ndef run_population_tensor_fixture(\n    *,\n    sidra_facts_path: str | Path,\n    run_dir: str | Path,\n    mode: str = "independent_denominator",\n) -> dict[str, object]:\n    out = write_population_tensor_fixture_bundle(sidra_facts_path=sidra_facts_path, run_dir=run_dir, mode=mode)\n    validation = validate_output_bundle(run_dir=str(out))\n    return {"run_dir": out, "validation": validation}\n\n\ndef run_population_tensor_plan(\n    *,\n    sidra_facts_path: str | Path,\n    mode: str = "independent_denominator",\n) -> dict[str, object]:\n    result = solve_population_tensor_from_sidra_anchor(sidra_facts_path=sidra_facts_path, mode=mode)\n    return result.as_manifest()\n\n\ndef run_population_dense_abort_check(*, localities: int, periods: int, strata: int = 1) -> dict[str, object]:\n    cells = dense_national_abort_check(localities=localities, periods=periods, strata=strata)\n    return {"status": "allowed", "cells": cells}\n'
